using backend.Data; using backend.Models; using Microsoft.EntityFrameworkCore;
namespace backend.Services;
public class EmiDueWorker(IServiceScopeFactory scopes,ILogger<EmiDueWorker> logger):BackgroundService
{
 protected override async Task ExecuteAsync(CancellationToken token){while(!token.IsCancellationRequested){try{await Process(token);}catch(OperationCanceledException)when(token.IsCancellationRequested){}catch(Exception e){logger.LogError(e,"EMI notification cycle failed.");}using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<CrmDbContext>();var minutes=(await db.NotificationSettings.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==1,token))?.DueCheckIntervalMinutes??60;await Task.Delay(TimeSpan.FromMinutes(Math.Clamp(minutes,1,1440)),token);}}
 public async Task Process(CancellationToken token){using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<CrmDbContext>();var push=scope.ServiceProvider.GetRequiredService<IOneSignalNotificationService>();var financial=scope.ServiceProvider.GetRequiredService<IFinancialService>();var now=DateTime.UtcNow.Date;var rows=await db.EmiInstallments.Include(x=>x.FinancialAgreement).ThenInclude(x=>x.Customer).Where(x=>x.DueDate<=now&&x.PaidAmount<x.ExpectedAmount&&x.FinancialAgreement.Customer.AssignedToId!=null).ToListAsync(token);foreach(var i in rows){var c=i.FinancialAgreement.Customer;var type=i.DueDate.Date<now?"EmiOverdue":i.PaidAmount>0?"EmiPartiallyPaid":"EmiDue";var key=$"{type}:customer:{c.Id}:installment:{i.Id}:due:{i.DueDate:yyyyMMdd}";if(await db.AppNotifications.AnyAsync(x=>x.UserId==c.AssignedToId&&x.EventKey==key,token))continue;var summary=await financial.SummaryAsync(c.Id,now);var due=i.ExpectedAmount-i.PaidAmount;var title=type=="EmiOverdue"?"EMI overdue":type=="EmiPartiallyPaid"?"EMI partially paid":"EMI due";var message=$"{c.Name}: {due:0.00} due, outstanding {summary.OutstandingBalance:0.00}.";db.AppNotifications.Add(new AppNotification{UserId=c.AssignedToId!.Value,CustomerId=c.Id,CustomerName=c.Name,FileId=c.FileId,DueAmount=due,OutstandingBalance=summary.OutstandingBalance,DueDate=i.DueDate,Title=title,Message=message,Type=type,Screen="customer",EventKey=key});await db.SaveChangesAsync(token);await push.SendFinancialPushAsync(c.AssignedToId.Value,c.Id,title,message,token);}}}
